#!/usr/bin/env python3
import os
import re
import json
import shutil
import zipfile
import xml.etree.ElementTree as ET

PLACEHOLDER_RE = re.compile(r"{{([^{}]+)}}")


def localname(tag: str) -> str:
    # tag may be '{uri}name' or 'name'
    if tag.startswith('{') and '}' in tag:
        return tag.split('}', 1)[1]
    return tag


def collect_namespaces(xml_path: str):
    ns = {}
    for event, elem in ET.iterparse(xml_path, events=("start-ns",)):
        prefix, uri = elem
        if prefix in ns and ns[prefix] == uri:
            continue
        ns[prefix] = uri
    return ns


def register_namespaces(nsmap):
    for prefix, uri in nsmap.items():
        # ElementTree uses '' for default namespace
        ET.register_namespace(prefix if prefix is not None else '', uri)


def replace_placeholders_in_section(section_xml_path: str, data: dict):
    nsmap = collect_namespaces(section_xml_path)
    register_namespaces(nsmap)

    tree = ET.parse(section_xml_path)
    root = tree.getroot()

    modified_paras = 0
    placeholders_replaced = 0
    placeholders_seen = set()

    # Process each paragraph
    for p in root.iter():
        if localname(p.tag).lower() != 'p':
            continue

        # Collect <hp:t> elements in doc order within this paragraph
        t_elems = [e for e in p.iter() if localname(e.tag).lower() == 't']
        if not t_elems:
            continue

        merged = ''.join((e.text or '') for e in t_elems)
        matches = list(PLACEHOLDER_RE.finditer(merged))
        if not matches:
            continue

        # Consolidate split runs: keep merged content in first <t>, blank the rest
        if len(t_elems) > 1:
            t_elems[0].text = merged
            for e in t_elems[1:]:
                e.text = ""
        else:
            t_elems[0].text = merged

        # Substitute placeholders
        def sub_fn(m):
            nonlocal placeholders_replaced
            key = m.group(1)
            placeholders_seen.add(key)
            if key in data:
                placeholders_replaced += 1
                return str(data[key])
            # leave unknown placeholders unchanged
            return m.group(0)

        new_text = PLACEHOLDER_RE.sub(sub_fn, t_elems[0].text or '')
        if new_text != (t_elems[0].text or ''):
            modified_paras += 1
            t_elems[0].text = new_text

    # Remove all linesegarray (layout cache) elements globally (safer)
    removed_linesegarray = 0
    for parent in root.iter():
        for child in list(parent):
            if localname(child.tag).lower() == 'linesegarray':
                parent.remove(child)
                removed_linesegarray += 1

    tree.write(section_xml_path, encoding='utf-8', xml_declaration=True)

    return {
        'section': os.path.basename(section_xml_path),
        'modified_paras': modified_paras,
        'placeholders_replaced': placeholders_replaced,
        'placeholders_seen': sorted(placeholders_seen),
        'removed_linesegarray': removed_linesegarray,
    }


def zip_dir_to_hwpx(src_dir: str, out_hwpx: str):
    if os.path.exists(out_hwpx):
        os.remove(out_hwpx)
    with zipfile.ZipFile(out_hwpx, 'w', compression=zipfile.ZIP_DEFLATED) as z:
        for root, dirs, files in os.walk(src_dir):
            dirs.sort()
            files.sort()
            for fn in files:
                abs_path = os.path.join(root, fn)
                rel_path = os.path.relpath(abs_path, src_dir)
                z.write(abs_path, rel_path)


def validate_hwpx(hwpx_path: str, data: dict):
    verify_dir = '/tmp/hwpx_verify'
    if os.path.exists(verify_dir):
        shutil.rmtree(verify_dir)
    os.makedirs(verify_dir, exist_ok=True)

    with zipfile.ZipFile(hwpx_path) as z:
        z.extractall(verify_dir)

    contents_dir = os.path.join(verify_dir, 'Contents')
    section_files = []
    if os.path.isdir(contents_dir):
        for fn in os.listdir(contents_dir):
            if fn.lower().startswith('section') and fn.lower().endswith('.xml'):
                section_files.append(os.path.join(contents_dir, fn))
    section_files.sort()

    # Search for placeholder patterns anywhere in section xml
    leftover_placeholders = []
    total_linesegarray = 0
    all_text = ''
    for p in section_files:
        raw = open(p, 'rb').read().decode('utf-8', errors='replace')
        if '{{' in raw or '}}' in raw:
            leftover_placeholders.append(os.path.basename(p))

        # Count linesegarray tags (case-insensitive by simple search)
        total_linesegarray += raw.lower().count('linesegarray')

        # Extract all <...:t> text quickly via XML parse
        nsmap = collect_namespaces(p)
        register_namespaces(nsmap)
        root = ET.parse(p).getroot()
        for e in root.iter():
            if localname(e.tag).lower() == 't':
                all_text += (e.text or '')
                all_text += '\n'

    missing_values = []
    for k, v in data.items():
        sv = str(v)
        if sv and sv not in all_text:
            missing_values.append(k)

    # Sanity checks for known static lines in this template
    static_checks = {
        '행사 공지문': '행사 공지문' in all_text,
        '비고: 사전 신청 필수': '비고: 사전 신청 필수' in all_text,
    }

    return {
        'section_files': [os.path.basename(p) for p in section_files],
        'leftover_placeholders_sections': leftover_placeholders,
        'total_linesegarray_tags_found': total_linesegarray,
        'missing_values_keys': missing_values,
        'static_checks': static_checks,
    }


def main():
    src_hwpx = '/root/event_announcement_template.hwpx'
    out_hwpx = '/root/event_announcement_ready.hwpx'
    data_path = '/root/event_data.json'

    work_dir = '/tmp/hwpx_work'
    if os.path.exists(work_dir):
        shutil.rmtree(work_dir)
    os.makedirs(work_dir, exist_ok=True)

    data = json.load(open(data_path, 'r', encoding='utf-8'))

    with zipfile.ZipFile(src_hwpx) as z:
        z.extractall(work_dir)

    contents_dir = os.path.join(work_dir, 'Contents')
    section_paths = []
    if os.path.isdir(contents_dir):
        for fn in os.listdir(contents_dir):
            if fn.lower().startswith('section') and fn.lower().endswith('.xml'):
                section_paths.append(os.path.join(contents_dir, fn))
    section_paths.sort()

    if not section_paths:
        raise SystemExit(f'No section*.xml found under {contents_dir}')

    results = []
    for sp in section_paths:
        results.append(replace_placeholders_in_section(sp, data))

    zip_dir_to_hwpx(work_dir, out_hwpx)

    v = validate_hwpx(out_hwpx, data)

    print('=== Replacement summary ===')
    for r in results:
        print(f"- {r['section']}: modified_paras={r['modified_paras']}, placeholders_replaced={r['placeholders_replaced']}, removed_linesegarray={r['removed_linesegarray']}")
        if r['placeholders_seen']:
            print('  placeholders_seen:', ', '.join(r['placeholders_seen']))

    print('\n=== Validation summary ===')
    print('sections:', ', '.join(v['section_files']))
    print('leftover_placeholders_sections:', v['leftover_placeholders_sections'])
    print('total_linesegarray_tags_found:', v['total_linesegarray_tags_found'])
    print('missing_values_keys:', v['missing_values_keys'])
    print('static_checks:', v['static_checks'])

    if v['leftover_placeholders_sections']:
        raise SystemExit('Validation failed: leftover {{...}} placeholders remain')
    if v['missing_values_keys']:
        raise SystemExit('Validation failed: some JSON values not found in output XML')
    if v['total_linesegarray_tags_found']:
        raise SystemExit('Validation failed: linesegarray tags still present')


if __name__ == '__main__':
    main()
